//! Durable, private diagnostic incident storage.
//!
//! This module deliberately keeps the wire schema and persistence rules together:
//! callers cannot persist an incident without passing the same validation and
//! sanitization used by the HTTP ingestion path. Files and administrator lookup
//! IDs are generated by the server; client-provided identifiers are never used as
//! path components.

use hmac::{Hmac, Mac};
use rand::{rngs::OsRng, RngCore};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::Sha256;
use std::{
    collections::{BTreeMap, HashMap},
    fmt,
    fs::{self, File, OpenOptions, TryLockError},
    io::{self, BufRead, BufReader, Read, Seek, SeekFrom, Write},
    net::{Ipv4Addr, Ipv6Addr},
    path::{Path, PathBuf},
    str::FromStr,
    sync::{
        atomic::{AtomicBool, Ordering},
        Mutex, MutexGuard,
    },
    time::Duration,
};

pub const INCIDENT_SCHEMA_VERSION: u16 = 1;
pub const STORED_RECORD_VERSION: u16 = 1;
pub const MAX_REQUEST_BYTES: usize = 256 * 1024;
/// Stored records include server metadata and redaction markers in addition to
/// the wire envelope. Every writer and reader uses this same ceiling so an
/// acknowledged record can never become invisible after restart.
pub const MAX_STORED_RECORD_BYTES: usize = MAX_REQUEST_BYTES + 16 * 1024;
pub const MAX_EVENTS: usize = 200;
pub const MAX_EVENT_MESSAGE_BYTES: usize = 2 * 1024;
pub const MAX_DETAIL_STRING_BYTES: usize = 1024;
pub const MAX_DETAIL_DEPTH: usize = 6;
pub const MAX_DETAIL_CONTAINER_ITEMS: usize = 32;
pub const MAX_DETAIL_NODES_PER_EVENT: usize = 256;
pub const MAX_LIST_LIMIT: usize = 200;
pub const DEFAULT_RETENTION: Duration = Duration::from_secs(14 * 24 * 60 * 60);
pub const DEFAULT_DISK_CAP_BYTES: u64 = 100 * 1024 * 1024;

const MAX_CLOCK_SKEW_MS: u64 = 5 * 60 * 1000;
const MAX_ENVELOPE_AGE_MS: u64 = 7 * 24 * 60 * 60 * 1000;
const MAX_CAP_EVICTION_HEADROOM_BYTES: u64 = 4 * 1024 * 1024;
const MILLIS_PER_DAY: u64 = 24 * 60 * 60 * 1000;
const STORAGE_PREFIX: &str = "diagnostics-";
const STORAGE_SUFFIX: &str = ".jsonl";
const STORAGE_LOCK_FILE: &str = ".echo-diagnostics.lock";
const IDENTITY_KEY_FILE: &str = ".echo-diagnostics-identity-key";
const IDENTITY_KEY_BYTES: usize = 32;
const MAX_STATIC_ROOT_SCAN_ENTRIES: usize = 100_000;
const MAX_STATIC_ROOT_SCAN_DEPTH: usize = 64;
const INCIDENT_ID_PREFIX: &str = "inc_";
const REDACTED_AUTH: &str = "[REDACTED_AUTH]";
const REDACTED_EMAIL: &str = "[REDACTED_EMAIL]";
const REDACTED_IP: &str = "[REDACTED_IP]";
const REDACTED_JWT: &str = "[REDACTED_JWT]";
const REDACTED_PATH: &str = "[REDACTED_PATH]";
const REDACTED_QUERY: &str = "[REDACTED_QUERY]";
const REDACTED_URL: &str = "[REDACTED_URL]";
const REDACTED_FIELD: &str = "[REDACTED_FIELD]";
const REDACTED_SDP: &str = "[REDACTED_SDP]";

