/// Returns true when a diagnostics root could be reached through one of the
/// unauthenticated static roots (or vice versa). Existing ancestors are
/// canonicalized so root-level symlink/junction overlap is detected even when
/// the final directory does not exist yet. Any filesystem link below a served
/// root is also rejected because a static file service may follow it after the
/// root-level check.
pub fn storage_path_overlaps(root: &Path, static_roots: &[&Path]) -> io::Result<bool> {
    let root = canonicalize_allow_missing(root)?;
    for static_root in static_roots {
        let canonical_static_root = canonicalize_allow_missing(static_root)?;
        if root.starts_with(&canonical_static_root)
            || canonical_static_root.starts_with(&root)
            || served_tree_contains_filesystem_link(static_root)?
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn served_tree_contains_filesystem_link(root: &Path) -> io::Result<bool> {
    let root_metadata = match fs::symlink_metadata(root) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(false),
        Err(error) => return Err(error),
    };
    if is_filesystem_link(&root_metadata) {
        return Ok(true);
    }
    if !root_metadata.is_dir() {
        return Ok(false);
    }

    let mut stack = vec![(root.to_path_buf(), 0usize)];
    let mut scanned_entries = 0usize;
    while let Some((directory, depth)) = stack.pop() {
        for entry in fs::read_dir(&directory)? {
            let entry = entry?;
            scanned_entries = scanned_entries.saturating_add(1);
            if scanned_entries > MAX_STATIC_ROOT_SCAN_ENTRIES {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "web-readable root exceeds the diagnostics isolation scan limit",
                ));
            }

            let metadata = fs::symlink_metadata(entry.path())?;
            if is_filesystem_link(&metadata) {
                return Ok(true);
            }
            if metadata.is_dir() {
                if depth >= MAX_STATIC_ROOT_SCAN_DEPTH {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "web-readable root exceeds the diagnostics isolation depth limit",
                    ));
                }
                stack.push((entry.path(), depth + 1));
            }
        }
    }
    Ok(false)
}

fn is_filesystem_link(metadata: &fs::Metadata) -> bool {
    if metadata.file_type().is_symlink() {
        return true;
    }
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        const FILE_ATTRIBUTE_REPARSE_POINT: u32 = 0x0400;
        metadata.file_attributes() & FILE_ATTRIBUTE_REPARSE_POINT != 0
    }
    #[cfg(not(windows))]
    {
        false
    }
}

fn canonicalize_allow_missing(path: &Path) -> io::Result<PathBuf> {
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()?.join(path)
    };
    let mut normalized = PathBuf::new();
    for component in absolute.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => {
                if !matches!(
                    normalized.components().next_back(),
                    Some(std::path::Component::Normal(_))
                ) {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidInput,
                        "path escapes its absolute root",
                    ));
                }
                normalized.pop();
            }
            _ => normalized.push(component.as_os_str()),
        }
    }

    let mut existing = normalized.as_path();
    let mut missing = Vec::new();
    while !existing.exists() {
        let name = existing.file_name().ok_or_else(|| {
            io::Error::new(io::ErrorKind::NotFound, "path has no existing ancestor")
        })?;
        missing.push(name.to_os_string());
        existing = existing.parent().ok_or_else(|| {
            io::Error::new(io::ErrorKind::NotFound, "path has no existing ancestor")
        })?;
    }
    let mut canonical = fs::canonicalize(existing)?;
    for component in missing.iter().rev() {
        canonical.push(component);
    }
    Ok(canonical)
}

fn load_or_create_identity_key(root: &Path) -> Result<[u8; IDENTITY_KEY_BYTES], DiagnosticsError> {
    let path = root.join(IDENTITY_KEY_FILE);
    match File::open(&path) {
        Ok(mut file) => {
            if file.metadata()?.len() != IDENTITY_KEY_BYTES as u64 {
                return Err(DiagnosticsError::Io(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "diagnostics identity key has an invalid length",
                )));
            }
            let mut key = [0u8; IDENTITY_KEY_BYTES];
            file.read_exact(&mut key)?;
            Ok(key)
        }
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            if !storage_files(root)?.is_empty() {
                return Err(DiagnosticsError::Io(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "diagnostics identity key is missing for a non-empty store",
                )));
            }

            let mut key = [0u8; IDENTITY_KEY_BYTES];
            OsRng.fill_bytes(&mut key);
            let mut file = OpenOptions::new()
                .create_new(true)
                .write(true)
                .open(&path)?;
            if let Err(error) = file.write_all(&key).and_then(|_| file.sync_all()) {
                drop(file);
                let _ = fs::remove_file(&path);
                return Err(error.into());
            }
            Ok(key)
        }
        Err(error) => Err(error.into()),
    }
}

impl DiagnosticStore {
    #[cfg(test)]
    pub fn open(root: impl AsRef<Path>) -> Result<Self, DiagnosticsError> {
        Self::open_internal(root.as_ref(), None)
    }

    pub fn open_with_policy(
        root: impl AsRef<Path>,
        now_ms: u64,
        policy: &RetentionPolicy,
    ) -> Result<Self, DiagnosticsError> {
        Self::open_internal(root.as_ref(), Some((now_ms, policy)))
    }

    fn open_internal(
        root: &Path,
        startup_policy: Option<(u64, &RetentionPolicy)>,
    ) -> Result<Self, DiagnosticsError> {
        fs::create_dir_all(root)?;
        let root = fs::canonicalize(root)?;
        let process_lock = OpenOptions::new()
            .create(true)
            .truncate(false)
            .read(true)
            .write(true)
            .open(root.join(STORAGE_LOCK_FILE))?;
        process_lock.try_lock().map_err(|error| match error {
            TryLockError::WouldBlock => DiagnosticsError::Io(io::Error::new(
                io::ErrorKind::WouldBlock,
                "diagnostics store is already open in another process",
            )),
            TryLockError::Error(error) => DiagnosticsError::Io(error),
        })?;
        recover_store_state(&root)?;
        let identity_key = load_or_create_identity_key(&root)?;
        if let Some((now_ms, policy)) = startup_policy {
            prune_directory(&root, now_ms, policy)?;
            recover_store_state(&root)?;
        }
        let index = load_index(&root)?;
        Ok(Self {
            root,
            _process_lock: process_lock,
            poisoned: AtomicBool::new(false),
            io_lock: Mutex::new(()),
            index: Mutex::new(index),
            identity_key,
        })
    }

    /// Parses, validates, sanitizes, and durably appends one authenticated batch.
    #[cfg(test)]
    pub fn ingest(
        &self,
        authenticated_identity: &str,
        raw_body: &[u8],
        received_at_ms: u64,
    ) -> Result<AppendOutcome, DiagnosticsError> {
        let envelope = parse_validate_and_sanitize(raw_body, received_at_ms)?;
        self.append_internal(authenticated_identity, envelope, received_at_ms, None)
    }

    /// Ingests one envelope while enforcing retention and capacity before the
    /// append is acknowledged. Old records may be evicted, but the incoming
    /// record is never written unless enough capacity has already been made.
    pub fn ingest_with_policy(
        &self,
        authenticated_identity: &str,
        raw_body: &[u8],
        received_at_ms: u64,
        policy: &RetentionPolicy,
    ) -> Result<AppendOutcome, DiagnosticsError> {
        let envelope = parse_validate_and_sanitize(raw_body, received_at_ms)?;
        self.append_internal(
            authenticated_identity,
            envelope,
            received_at_ms,
            Some(policy),
        )
    }

    /// Appends a typed envelope. Validation and sanitization are intentionally
    /// repeated here so internal callers cannot bypass the ingestion boundary.
    #[cfg(test)]
    pub fn append(
        &self,
        authenticated_identity: &str,
        envelope: IncidentEnvelope,
        received_at_ms: u64,
    ) -> Result<AppendOutcome, DiagnosticsError> {
        self.append_internal(authenticated_identity, envelope, received_at_ms, None)
    }

    fn append_internal(
        &self,
        authenticated_identity: &str,
        mut envelope: IncidentEnvelope,
        received_at_ms: u64,
        policy: Option<&RetentionPolicy>,
    ) -> Result<AppendOutcome, DiagnosticsError> {
        self.ensure_healthy()?;
        validate_envelope(&envelope, received_at_ms)?;
        sanitize_envelope(&mut envelope);

        validate_server_identity(authenticated_identity)?;
        let authenticated_identity_digest =
            identity_digest(&self.identity_key, authenticated_identity);
        let authenticated_identity = sanitize_text(authenticated_identity);
        let payload_digest = payload_digest(&envelope)?;

        let _io_guard = lock(&self.io_lock)?;
        self.ensure_healthy()?;
        let mut index = lock(&self.index)?;
        let envelope_key = (
            authenticated_identity_digest.clone(),
            envelope.envelope_id.clone(),
        );
        if let Some(existing) = index.by_envelope_key.get(&envelope_key) {
            return Ok(if existing.payload_digest == payload_digest {
                AppendOutcome::Duplicate {
                    incident_id: existing.incident_id.clone(),
                }
            } else {
                AppendOutcome::Conflict {
                    incident_id: existing.incident_id.clone(),
                }
            });
        }

        let incident_id = generate_unique_incident_id(&index)?;
        let record = StoredIncident {
            record_version: STORED_RECORD_VERSION,
            incident_id: incident_id.clone(),
            received_at_ms,
            authenticated_identity,
            authenticated_identity_digest,
            payload_digest: payload_digest.clone(),
            envelope,
        };
        let line = serde_json::to_vec(&record).map_err(|_| DiagnosticsError::Serialization)?;
        if line.len() > MAX_STORED_RECORD_BYTES {
            return Err(DiagnosticsError::BodyTooLarge);
        }

        if let Some(policy) = policy {
            let report = match prune_for_append(
                &self.root,
                received_at_ms,
                policy,
                line.len().saturating_add(1) as u64,
            ) {
                Ok(report) => report,
                Err(error) => {
                    self.reconcile_or_poison(&mut index);
                    return Err(error);
                }
            };
            if report.changed {
                match self.recover_and_rebuild_index() {
                    Ok(rebuilt) => *index = rebuilt,
                    Err(error) => {
                        self.poisoned.store(true, Ordering::Release);
                        return Err(error);
                    }
                }
            }
        }

        let file_name = storage_file_name(received_at_ms);
        let path = self.root.join(&file_name);
        if let Err(error) = append_json_line(&path, &line) {
            // The final sync can fail after the complete line reached disk.
            // Re-sync visible bytes, recover a torn tail if needed, and rebuild
            // before returning so a retry cannot append a second incident. If
            // durability still cannot be established, poison the store.
            if OpenOptions::new()
                .read(true)
                .write(true)
                .open(&path)
                .and_then(|file| file.sync_data())
                .is_err()
            {
                self.poisoned.store(true, Ordering::Release);
                return Err(error.into());
            }
            self.reconcile_or_poison(&mut index);
            return Err(error.into());
        }

        let entry = IndexEntry {
            incident_id: incident_id.clone(),
            payload_digest,
            file_name,
        };
        index.by_envelope_key.insert(envelope_key, entry.clone());
        index.by_incident_id.insert(incident_id.clone(), entry);

        Ok(AppendOutcome::Stored { incident_id })
    }

    /// Returns newest-first summaries. The result is always bounded even when a
    /// caller supplies a larger limit.
    pub fn list_summaries(
        &self,
        limit: usize,
        before: Option<(u64, String)>,
    ) -> Result<Vec<IncidentSummary>, DiagnosticsError> {
        self.ensure_healthy()?;
        let limit = limit.min(MAX_LIST_LIMIT);
        if limit == 0 {
            return Ok(Vec::new());
        }
        if let Some((_, incident_id)) = &before {
            validate_incident_id(incident_id)?;
        }

        let _io_guard = lock(&self.io_lock)?;
        self.ensure_healthy()?;
        let mut summaries = Vec::with_capacity(limit + 1);
        for_each_record(&self.root, |record, _| {
            if let Some((before_received_at_ms, before_incident_id)) = &before {
                if record.received_at_ms > *before_received_at_ms
                    || (record.received_at_ms == *before_received_at_ms
                        && record.incident_id >= *before_incident_id)
                {
                    return;
                }
            }

            summaries.push(IncidentSummary::from(&record));
            if summaries.len() > limit * 2 {
                sort_summaries(&mut summaries);
                summaries.truncate(limit);
            }
        })?;
        sort_summaries(&mut summaries);
        summaries.truncate(limit);
        Ok(summaries)
    }

    /// Looks up a record only by the opaque server-generated incident ID.
    pub fn get_incident(
        &self,
        incident_id: &str,
    ) -> Result<Option<StoredIncident>, DiagnosticsError> {
        self.ensure_healthy()?;
        validate_incident_id(incident_id)?;
        let _io_guard = lock(&self.io_lock)?;
        self.ensure_healthy()?;
        let file_name = {
            let index = lock(&self.index)?;
            index
                .by_incident_id
                .get(incident_id)
                .map(|entry| entry.file_name.clone())
        };
        let Some(file_name) = file_name else {
            return Ok(None);
        };
        let path = checked_storage_path(&self.root, &file_name)?;
        let mut record = find_record(&path, incident_id)?;
        if let Some(record) = record.as_mut() {
            sanitize_stored_incident(record);
        }
        Ok(record)
    }

    /// Produces stable, pretty, already-redacted JSON suitable for an explicit
    /// administrator download. Raw JSONL bytes are never exposed.
    pub fn redacted_download_json(
        &self,
        incident_id: &str,
    ) -> Result<Option<String>, DiagnosticsError> {
        let Some(record) = self.get_incident(incident_id)? else {
            return Ok(None);
        };
        let mut json =
            serde_json::to_string_pretty(&record).map_err(|_| DiagnosticsError::Serialization)?;
        json.push('\n');
        Ok(Some(json))
    }

    /// Removes one incident through a locked rewrite. The client envelope ID is
    /// not accepted here and never becomes a path component.
    pub fn delete_incident(&self, incident_id: &str) -> Result<bool, DiagnosticsError> {
        self.ensure_healthy()?;
        validate_incident_id(incident_id)?;
        let _io_guard = lock(&self.io_lock)?;
        self.ensure_healthy()?;
        let mut index = lock(&self.index)?;
        let Some(entry) = index.by_incident_id.get(incident_id).cloned() else {
            return Ok(false);
        };
        let path = checked_storage_path(&self.root, &entry.file_name)?;
        match rewrite_without_incident(&path, incident_id) {
            Ok(true) => {}
            Ok(false) => return Ok(false),
            Err(error) => {
                self.reconcile_or_poison(&mut index);
                return Err(error.into());
            }
        }

        index.by_incident_id.remove(incident_id);
        index
            .by_envelope_key
            .retain(|_, candidate| candidate.incident_id != incident_id);
        Ok(true)
    }

    pub fn prune(
        &self,
        now_ms: u64,
        policy: &RetentionPolicy,
    ) -> Result<PruneReport, DiagnosticsError> {
        self.ensure_healthy()?;
        let _io_guard = lock(&self.io_lock)?;
        self.ensure_healthy()?;
        let report = prune_directory(&self.root, now_ms, policy);
        let mut index = lock(&self.index)?;
        match self.recover_and_rebuild_index() {
            Ok(rebuilt) => *index = rebuilt,
            Err(error) => {
                self.poisoned.store(true, Ordering::Release);
                return Err(error);
            }
        }
        report
    }

    fn ensure_healthy(&self) -> Result<(), DiagnosticsError> {
        if self.poisoned.load(Ordering::Acquire) {
            Err(DiagnosticsError::LockPoisoned)
        } else {
            Ok(())
        }
    }

    fn recover_and_rebuild_index(&self) -> Result<StoreIndex, DiagnosticsError> {
        recover_store_state(&self.root)?;
        load_index(&self.root)
    }

    fn reconcile_or_poison(&self, index: &mut StoreIndex) {
        match self.recover_and_rebuild_index() {
            Ok(rebuilt) => *index = rebuilt,
            Err(_) => self.poisoned.store(true, Ordering::Release),
        }
    }
}

fn lock<T>(mutex: &Mutex<T>) -> Result<MutexGuard<'_, T>, DiagnosticsError> {
    mutex.lock().map_err(|_| DiagnosticsError::LockPoisoned)
}

pub fn parse_validate_and_sanitize(
    raw_body: &[u8],
    now_ms: u64,
) -> Result<IncidentEnvelope, DiagnosticsError> {
    if raw_body.len() > MAX_REQUEST_BYTES {
        return Err(DiagnosticsError::BodyTooLarge);
    }
    let mut envelope: IncidentEnvelope =
        serde_json::from_slice(raw_body).map_err(|_| DiagnosticsError::InvalidJson)?;
    validate_envelope(&envelope, now_ms)?;
    sanitize_envelope(&mut envelope);
    Ok(envelope)
}

pub fn validate_envelope(envelope: &IncidentEnvelope, now_ms: u64) -> Result<(), ValidationError> {
    if envelope.schema_version != INCIDENT_SCHEMA_VERSION {
        return Err(ValidationError::UnsupportedSchemaVersion);
    }
    validate_uuid(&envelope.envelope_id, "envelope_id")?;
    validate_uuid(&envelope.install_id, "install_id")?;
    validate_uuid(&envelope.session_id, "session_id")?;

    validate_envelope_timestamp(envelope.captured_at_ms, now_ms, "captured_at_ms")?;
    validate_envelope_timestamp(envelope.sent_at_ms, now_ms, "sent_at_ms")?;
    if envelope.sent_at_ms < envelope.captured_at_ms {
        return Err(ValidationError::InvalidTimestamp("sent_at_ms"));
    }

    validate_metadata_string(&envelope.app.version, 32, "app.version")?;
    validate_git_sha(&envelope.app.git_sha)?;
    validate_channel(&envelope.app.channel)?;
    validate_runtime_info(&envelope.app.runtimes)?;
    validate_optional_metadata(
        envelope.platform.os_version.as_deref(),
        64,
        "platform.os_version",
    )?;
    validate_optional_metadata(
        envelope.platform.os_build.as_deref(),
        64,
        "platform.os_build",
    )?;

    if envelope.events.is_empty() {
        return Err(ValidationError::EmptyEvents);
    }
    if envelope.events.len() > MAX_EVENTS {
        return Err(ValidationError::TooManyEvents);
    }

    let mut prior_sequence = None;
    let mut prior_timestamp = None;
    for event in &envelope.events {
        if event.timestamp_ms < envelope.captured_at_ms
            || event.timestamp_ms > envelope.sent_at_ms
            || prior_sequence
                .map(|sequence| event.sequence <= sequence)
                .unwrap_or(false)
            || prior_timestamp
                .map(|timestamp| event.timestamp_ms < timestamp)
                .unwrap_or(false)
        {
            return Err(ValidationError::InvalidEventOrder);
        }
        prior_sequence = Some(event.sequence);
        prior_timestamp = Some(event.timestamp_ms);

        validate_event_code(event.event_type, &event.code)?;
        if let Some(fingerprint) = &event.fingerprint {
            validate_code(fingerprint, 128, "event.fingerprint")?;
        }
        if let Some(message) = &event.message {
            validate_free_text(message, MAX_EVENT_MESSAGE_BYTES, "event.message")?;
        }
        if event.details.len() > MAX_DETAIL_CONTAINER_ITEMS {
            return Err(ValidationError::DetailContainerTooLarge);
        }
        let mut nodes = 0;
        for (key, value) in &event.details {
            validate_detail_key(key)?;
            validate_detail_value(value, 1, &mut nodes)?;
        }
    }
    Ok(())
}

fn validate_runtime_info(runtime: &RuntimeInfo) -> Result<(), ValidationError> {
    validate_optional_metadata(runtime.browser_name.as_deref(), 64, "runtime.browser_name")?;
    validate_optional_metadata(
        runtime.browser_version.as_deref(),
        64,
        "runtime.browser_version",
    )?;
    validate_optional_metadata(
        runtime.webview_version.as_deref(),
        64,
        "runtime.webview_version",
    )?;
    validate_optional_metadata(
        runtime.livekit_version.as_deref(),
        64,
        "runtime.livekit_version",
    )?;
    validate_optional_metadata(
        runtime.tauri_version.as_deref(),
        64,
        "runtime.tauri_version",
    )?;
    Ok(())
}

fn validate_optional_metadata(
    value: Option<&str>,
    max_bytes: usize,
    field: &'static str,
) -> Result<(), ValidationError> {
    if let Some(value) = value {
        validate_metadata_string(value, max_bytes, field)?;
    }
    Ok(())
}

fn validate_envelope_timestamp(
    value: u64,
    now_ms: u64,
    field: &'static str,
) -> Result<(), ValidationError> {
    if value == 0
        || value > now_ms.saturating_add(MAX_CLOCK_SKEW_MS)
        || value.saturating_add(MAX_ENVELOPE_AGE_MS) < now_ms
    {
        return Err(ValidationError::InvalidTimestamp(field));
    }
    Ok(())
}

fn validate_uuid(value: &str, field: &'static str) -> Result<(), ValidationError> {
    if value.len() != 36 {
        return Err(ValidationError::InvalidIdentifier(field));
    }
    for (index, byte) in value.bytes().enumerate() {
        if matches!(index, 8 | 13 | 18 | 23) {
            if byte != b'-' {
                return Err(ValidationError::InvalidIdentifier(field));
            }
        } else if !matches!(byte, b'0'..=b'9' | b'a'..=b'f') {
            return Err(ValidationError::InvalidIdentifier(field));
        }
    }
    Ok(())
}

fn validate_incident_id(value: &str) -> Result<(), ValidationError> {
    let Some(hex) = value.strip_prefix(INCIDENT_ID_PREFIX) else {
        return Err(ValidationError::InvalidIdentifier("incident_id"));
    };
    if hex.len() != 32
        || !hex
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(ValidationError::InvalidIdentifier("incident_id"));
    }
    Ok(())
}

fn validate_git_sha(value: &str) -> Result<(), ValidationError> {
    // Echo's stamped viewer build uses a short Git revision. Keeping this
    // deliberately short prevents arbitrary 32/64-byte credentials from being
    // smuggled into a field that otherwise looks like hexadecimal metadata.
    if !(7..=12).contains(&value.len())
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
    {
        return Err(ValidationError::InvalidString("app.git_sha"));
    }
    Ok(())
}

fn validate_channel(value: &str) -> Result<(), ValidationError> {
    const CHANNELS: &[&str] = &[
        "web",
        "web-canary",
        "web-smoke",
        "desktop-stable",
        "desktop-canary",
        "test",
    ];
    if CHANNELS.contains(&value) {
        Ok(())
    } else {
        Err(ValidationError::InvalidString("app.channel"))
    }
}

fn validate_event_code(
    event_type: DiagnosticEventType,
    value: &str,
) -> Result<(), ValidationError> {
    validate_code(value, 96, "event.code")?;
    if !value.split('.').all(|segment| {
        segment
            .as_bytes()
            .first()
            .map(|byte| byte.is_ascii_alphabetic())
            .unwrap_or(false)
            && segment
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-'))
    }) {
        return Err(ValidationError::InvalidString("event.code"));
    }
    let prefixes: &[&str] = match event_type {
        DiagnosticEventType::SessionStart
        | DiagnosticEventType::SessionEnd
        | DiagnosticEventType::UncleanShutdown => &["session."],
        DiagnosticEventType::JavascriptError | DiagnosticEventType::UnhandledRejection => {
            &["javascript.", "promise."]
        }
        DiagnosticEventType::ConsoleWarning | DiagnosticEventType::ConsoleError => &["console."],
        DiagnosticEventType::Permission => {
            &["permission.", "microphone.", "camera.", "screen_share."]
        }
        DiagnosticEventType::Media => &["media.", "microphone.", "camera.", "screen_share."],
        DiagnosticEventType::Connection => &["connection.", "ice.", "livekit.", "sfu.", "webrtc."],
        DiagnosticEventType::Reconnect => &["reconnect.", "connection."],
        DiagnosticEventType::TauriIpcError => &["tauri."],
        DiagnosticEventType::NativeError => &["native."],
    };
    if prefixes.iter().any(|prefix| value.starts_with(prefix)) {
        Ok(())
    } else {
        Err(ValidationError::InvalidString("event.code"))
    }
}

fn validate_code(
    value: &str,
    max_bytes: usize,
    field: &'static str,
) -> Result<(), ValidationError> {
    if value.is_empty()
        || value.len() > max_bytes
        || !value.as_bytes()[0].is_ascii_alphanumeric()
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-' | b'.'))
    {
        return Err(ValidationError::InvalidString(field));
    }
    Ok(())
}

fn validate_metadata_string(
    value: &str,
    max_bytes: usize,
    field: &'static str,
) -> Result<(), ValidationError> {
    if value.is_empty() {
        return Err(ValidationError::InvalidString(field));
    }
    if value.len() > max_bytes {
        return Err(ValidationError::StringTooLong(field));
    }
    if value.chars().any(char::is_control) {
        return Err(ValidationError::InvalidString(field));
    }
    Ok(())
}

fn validate_free_text(
    value: &str,
    max_bytes: usize,
    field: &'static str,
) -> Result<(), ValidationError> {
    if value.len() > max_bytes {
        return Err(ValidationError::StringTooLong(field));
    }
    if value
        .chars()
        .any(|character| character.is_control() && !matches!(character, '\n' | '\r' | '\t'))
    {
        return Err(ValidationError::InvalidString(field));
    }
    Ok(())
}

fn validate_server_identity(value: &str) -> Result<(), ValidationError> {
    validate_free_text(value, 128, "authenticated_identity")?;
    if value.is_empty() {
        return Err(ValidationError::InvalidString("authenticated_identity"));
    }
    Ok(())
}

fn validate_detail_key(key: &str) -> Result<(), ValidationError> {
    if key.is_empty()
        || key.len() > 48
        || !key.as_bytes()[0].is_ascii_lowercase()
        || !key
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'_')
    {
        return Err(ValidationError::InvalidDetailKey);
    }
    if !is_allowed_detail_key(key) {
        return Err(ValidationError::DisallowedDetailKey);
    }
    Ok(())
}

fn is_allowed_detail_key(key: &str) -> bool {
    matches!(
        key,
        "action"
            | "actual"
            | "attempt"
            | "audio"
            | "bitrate_bps"
            | "browser"
            | "camera"
            | "candidate_type"
            | "channel_count"
            | "clean"
            | "codec"
            | "column"
            | "connection_state"
            | "count"
            | "current"
            | "denied"
            | "device_count"
            | "device_kind"
            | "direction"
            | "duration_ms"
            | "enabled"
            | "ended"
            | "energy_detected"
            | "error_code"
            | "expected"
            | "failure_stage"
            | "fps"
            | "granted"
            | "height"
            | "ice_state"
            | "jitter_ms"
            | "kind"
            | "line"
            | "media_kind"
            | "microphone"
            | "muted"
            | "nack_count"
            | "network_state"
            | "operation"
            | "output"
            | "packet_loss_percent"
            | "permission"
            | "permission_state"
            | "phase"
            | "pli_count"
            | "previous"
            | "protocol"
            | "published"
            | "reconnect_count"
            | "requested"
            | "resolution"
            | "result"
            | "room_state"
            | "rtt_ms"
            | "sample_rate_hz"
            | "screen"
            | "selected"
            | "source_category"
            | "stage"
            | "started"
            | "state"
            | "status"
            | "subscribed"
            | "target"
            | "track_state"
            | "transport"
            | "unclean"
            | "video"
            | "visibility"
            | "width"
    )
}

fn validate_detail_value(
    value: &Value,
    depth: usize,
    nodes: &mut usize,
) -> Result<(), ValidationError> {
    if depth > MAX_DETAIL_DEPTH {
        return Err(ValidationError::DetailTooDeep);
    }
    *nodes += 1;
    if *nodes > MAX_DETAIL_NODES_PER_EVENT {
        return Err(ValidationError::TooManyDetailNodes);
    }

    match value {
        Value::Null | Value::Bool(_) | Value::Number(_) => Ok(()),
        Value::String(value) => {
            validate_free_text(value, MAX_DETAIL_STRING_BYTES, "event.details string")
        }
        Value::Array(values) => {
            if values.len() > MAX_DETAIL_CONTAINER_ITEMS {
                return Err(ValidationError::DetailContainerTooLarge);
            }
            for value in values {
                validate_detail_value(value, depth + 1, nodes)?;
            }
            Ok(())
        }
        Value::Object(values) => {
            if values.len() > MAX_DETAIL_CONTAINER_ITEMS {
                return Err(ValidationError::DetailContainerTooLarge);
            }
            for (key, value) in values {
                validate_detail_key(key)?;
                validate_detail_value(value, depth + 1, nodes)?;
            }
            Ok(())
        }
    }
}

pub fn sanitize_envelope(envelope: &mut IncidentEnvelope) {
    envelope.app.version = sanitize_text(&envelope.app.version);
    envelope.app.git_sha = sanitize_text(&envelope.app.git_sha);
    envelope.app.channel = sanitize_text(&envelope.app.channel);
    sanitize_optional_text(&mut envelope.app.runtimes.browser_name);
    sanitize_optional_text(&mut envelope.app.runtimes.browser_version);
    sanitize_optional_text(&mut envelope.app.runtimes.webview_version);
    sanitize_optional_text(&mut envelope.app.runtimes.livekit_version);
    sanitize_optional_text(&mut envelope.app.runtimes.tauri_version);
    sanitize_optional_text(&mut envelope.platform.os_version);
    sanitize_optional_text(&mut envelope.platform.os_build);
    for event in &mut envelope.events {
        event.code = sanitize_text(&event.code);
        // A client-provided opaque fingerprint is indistinguishable from a
        // credential. Grouping remains available through the closed event type
        // and attested code, so the raw fingerprint is intentionally dropped.
        event.fingerprint = None;
        // Free-form messages are also an accidental log/chat exfiltration
        // channel. Browser diagnostics trade detail for privacy and persist
        // only the closed code plus allowlisted structured fields.
        event.message = None;
        for (key, value) in &mut event.details {
            sanitize_value(key, value);
        }
    }
}

fn sanitize_optional_text(value: &mut Option<String>) {
    if let Some(value) = value.as_mut() {
        *value = sanitize_text(value);
    }
}

fn sanitize_stored_incident(record: &mut StoredIncident) {
    record.authenticated_identity = sanitize_text(&record.authenticated_identity);
    sanitize_envelope(&mut record.envelope);
}

fn sanitize_value(key: &str, value: &mut Value) {
    if is_sensitive_key(key) {
        *value = Value::String(REDACTED_FIELD.to_string());
        return;
    }
    match value {
        Value::String(text) => *text = sanitize_text(text),
        Value::Array(values) => {
            for value in values {
                sanitize_value("", value);
            }
        }
        Value::Object(values) => {
            for (key, value) in values {
                sanitize_value(key, value);
            }
        }
        Value::Null | Value::Bool(_) | Value::Number(_) => {}
    }
}

fn is_sensitive_key(key: &str) -> bool {
    let normalized = normalize_sensitive_key(key);
    [
        "auth",
        "authorization",
        "bearer",
        "candidate",
        "chat",
        "clipboard",
        "content",
        "cookie",
        "credential",
        "device_label",
        "email",
        "frame",
        "jwt",
        "key",
        "password",
        "path",
        "process",
        "screenshot",
        "sdp",
        "secret",
        "serial",
        "ssid",
        "token",
        "window_title",
    ]
    .iter()
    .any(|needle| contains_key_component(&normalized, needle))
}

fn contains_key_component(normalized: &str, needle: &str) -> bool {
    normalized.match_indices(needle).any(|(start, _)| {
        let end = start + needle.len();
        (start == 0 || normalized.as_bytes()[start - 1] == b'_')
            && (end == normalized.len() || normalized.as_bytes()[end] == b'_')
    })
}

fn normalize_sensitive_key(key: &str) -> String {
    let mut normalized = String::with_capacity(key.len());
    let mut previous_was_lower_or_digit = false;
    for character in key.chars() {
        if character.is_ascii_uppercase() {
            if previous_was_lower_or_digit && !normalized.ends_with('_') {
                normalized.push('_');
            }
            normalized.push(character.to_ascii_lowercase());
            previous_was_lower_or_digit = false;
        } else if character == '-' || character.is_ascii_whitespace() {
            if !normalized.ends_with('_') {
                normalized.push('_');
            }
            previous_was_lower_or_digit = false;
        } else {
            normalized.push(character.to_ascii_lowercase());
            previous_was_lower_or_digit =
                character.is_ascii_lowercase() || character.is_ascii_digit();
        }
    }
    normalized
}

/// Redacts high-risk values without logging or returning the original match.
/// The recognizers intentionally over-redact ambiguous values.
pub fn sanitize_text(input: &str) -> String {
    let text = redact_sdp_and_candidate_lines(input);
    let text = redact_with(&text, detect_url);
    let text = redact_with(&text, detect_file_uri);
    let text = redact_with(&text, detect_absolute_path);
    let text = redact_url_queries(&text);
    let text = redact_with(&text, detect_auth_scheme_value);
    let text = redact_with(&text, detect_labeled_secret);
    let text = redact_with(&text, detect_jwt);
    let text = redact_with(&text, detect_opaque_token);
    let text = redact_with(&text, detect_email);
    let text = redact_with(&text, detect_bracketed_ipv6);
    let text = redact_with(&text, detect_ipv6);
    let mut text = redact_with(&text, detect_ipv4);
    truncate_to_byte_len(&mut text, input.len());
    text
}

fn truncate_to_byte_len(value: &mut String, maximum_bytes: usize) {
    if value.len() <= maximum_bytes {
        return;
    }
    let mut end = maximum_bytes;
    while !value.is_char_boundary(end) {
        end = end.saturating_sub(1);
    }
    value.truncate(end);
}

type Detector = fn(&str, usize) -> Option<(usize, &'static str)>;

fn redact_with(input: &str, detector: Detector) -> String {
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    while cursor < input.len() {
        if let Some((end, replacement)) = detector(input, cursor) {
            if end > cursor {
                output.push_str(replacement);
                cursor = end;
                continue;
            }
        }
        let character = input[cursor..]
            .chars()
            .next()
            .expect("cursor is inside the string");
        output.push(character);
        cursor += character.len_utf8();
    }
    output
}

fn redact_sdp_and_candidate_lines(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    for line in input.split_inclusive('\n') {
        let content = line.strip_suffix('\n').unwrap_or(line);
        let normalized = content.trim().to_ascii_lowercase();
        let sensitive = normalized.contains("candidate:")
            || normalized.contains("ice-ufrag")
            || normalized.contains("ice-pwd")
            || normalized == "v=0"
            || normalized.starts_with("o=")
            || normalized.starts_with("c=in ip")
            || normalized.starts_with("a=fingerprint:");
        if sensitive {
            output.push_str(REDACTED_SDP);
        } else {
            output.push_str(content);
        }
        if line.ends_with('\n') {
            output.push('\n');
        }
    }
    output
}

fn detect_url(input: &str, start: usize) -> Option<(usize, &'static str)> {
    const SCHEMES: &[&str] = &["https://", "http://", "wss://", "ws://"];
    if !SCHEMES
        .iter()
        .any(|scheme| starts_with_ascii_case_insensitive(&input[start..], scheme))
        || !is_token_boundary(input, start)
    {
        return None;
    }
    let end = consume_until(input, start, |character| {
        character.is_whitespace() || matches!(character, '"' | '\'' | '<' | '>' | ')' | ']' | '}')
    });
    Some((end, REDACTED_URL))
}

fn detect_file_uri(input: &str, start: usize) -> Option<(usize, &'static str)> {
    if !starts_with_ascii_case_insensitive(&input[start..], "file://")
        || !is_path_boundary(input, start)
    {
        return None;
    }
    let end = consume_until(input, start, |character| {
        matches!(
            character,
            '\n' | '\r' | '\t' | '"' | '\'' | '<' | '>' | '|' | ',' | ';' | ')' | ']' | '}'
        )
    });
    Some((end, REDACTED_PATH))
}

fn detect_absolute_path(input: &str, start: usize) -> Option<(usize, &'static str)> {
    let tail = &input[start..];
    let windows = tail.len() >= 3
        && tail.as_bytes()[0].is_ascii_alphabetic()
        && tail.as_bytes()[1] == b':'
        && matches!(tail.as_bytes()[2], b'/' | b'\\');
    let unc = tail.starts_with("\\\\");
    let unix = tail.starts_with('/')
        && tail
            .as_bytes()
            .get(1)
            .map(|byte| *byte != b'/')
            .unwrap_or(false);
    let tilde = tail.starts_with("~/") || tail.starts_with("~\\");
    if !(windows || unc || unix || tilde) || !is_path_boundary(input, start) {
        return None;
    }

    let end = consume_until(input, start, |character| {
        matches!(
            character,
            '\n' | '\r' | '\t' | '"' | '\'' | '<' | '>' | '|' | ',' | ';' | ')' | ']' | '}'
        )
    });
    Some((end, REDACTED_PATH))
}

fn redact_url_queries(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    while cursor < input.len() {
        if input.as_bytes()[cursor] == b'?' && looks_like_query_start(input, cursor) {
            output.push('?');
            output.push_str(REDACTED_QUERY);
            cursor += 1;
            while cursor < input.len() {
                let character = input[cursor..]
                    .chars()
                    .next()
                    .expect("cursor is inside the string");
                if character.is_whitespace()
                    || matches!(character, '"' | '\'' | '<' | '>' | ')' | ']' | '}')
                {
                    break;
                }
                cursor += character.len_utf8();
            }
            continue;
        }
        let character = input[cursor..]
            .chars()
            .next()
            .expect("cursor is inside the string");
        output.push(character);
        cursor += character.len_utf8();
    }
    output
}

fn looks_like_query_start(input: &str, question: usize) -> bool {
    let after_end = input[question + 1..]
        .char_indices()
        .find(|(_, character)| {
            character.is_whitespace()
                || matches!(character, '"' | '\'' | '<' | '>' | ')' | ']' | '}')
        })
        .map(|(offset, _)| question + 1 + offset)
        .unwrap_or(input.len());
    input[question + 1..after_end].contains('=')
}

fn detect_auth_scheme_value(input: &str, start: usize) -> Option<(usize, &'static str)> {
    const SCHEMES: &[&str] = &["bearer", "basic", "digest"];
    let scheme = SCHEMES.iter().find(|scheme| {
        starts_with_ascii_case_insensitive(&input[start..], scheme)
            && is_word_boundary(input, start)
            && is_word_end(input, start + scheme.len())
    })?;
    let mut cursor = start + scheme.len();
    if cursor >= input.len()
        || !input[cursor..]
            .chars()
            .next()
            .map(char::is_whitespace)
            .unwrap_or(false)
    {
        return None;
    }
    cursor = skip_ascii_whitespace(input, cursor);
    let end = if *scheme == "digest" {
        consume_until(input, cursor, |character| matches!(character, '\n' | '\r'))
    } else {
        consume_secret_value(input, cursor)
    };
    (end > cursor).then_some((end, REDACTED_AUTH))
}

fn detect_labeled_secret(input: &str, start: usize) -> Option<(usize, &'static str)> {
    if !is_word_boundary(input, start) || !input.as_bytes()[start].is_ascii_alphabetic() {
        return None;
    }
    let label_end = consume_while(input, start, |byte| {
        byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-')
    });
    let mut cursor = label_end;
    cursor = skip_ascii_whitespace_and_quotes(input, cursor);
    if cursor >= input.len() || !matches!(input.as_bytes()[cursor], b':' | b'=') {
        return None;
    }
    if !is_sensitive_key(&input[start..label_end]) {
        return None;
    }
    cursor += 1;
    cursor = skip_ascii_whitespace_and_quotes(input, cursor);
    let end = consume_until(input, cursor, |character| matches!(character, '\n' | '\r'));
    (end > cursor).then_some((end, REDACTED_AUTH))
}

fn detect_jwt(input: &str, start: usize) -> Option<(usize, &'static str)> {
    if !input[start..].starts_with("eyJ") || !is_token_boundary(input, start) {
        return None;
    }
    let end = consume_while(input, start, |byte| {
        byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-' | b'.')
    });
    let candidate = &input[start..end];
    let mut parts = candidate.split('.');
    let valid = parts.next().map(|part| part.len() >= 3).unwrap_or(false)
        && parts.next().map(|part| part.len() >= 4).unwrap_or(false)
        && parts.next().map(|part| part.len() >= 4).unwrap_or(false)
        && parts.next().is_none();
    valid.then_some((end, REDACTED_JWT))
}

fn detect_opaque_token(input: &str, start: usize) -> Option<(usize, &'static str)> {
    let first = input.as_bytes()[start];
    if !first.is_ascii_alphanumeric() || !is_token_boundary(input, start) {
        return None;
    }
    let end = consume_while(input, start, |byte| {
        byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-')
    });
    let candidate = &input[start..end];
    if candidate.len() < 32 {
        return None;
    }
    let has_lower = candidate.bytes().any(|byte| byte.is_ascii_lowercase());
    let has_upper = candidate.bytes().any(|byte| byte.is_ascii_uppercase());
    let has_digit = candidate.bytes().any(|byte| byte.is_ascii_digit());
    ((has_lower as u8 + has_upper as u8 + has_digit as u8) >= 2).then_some((end, REDACTED_FIELD))
}

fn detect_email(input: &str, start: usize) -> Option<(usize, &'static str)> {
    let first = input.as_bytes()[start];
    if !is_email_local_byte(first) || !is_email_boundary(input, start) {
        return None;
    }
    let mut end = consume_while(input, start, is_email_candidate_byte);
    while end > start && matches!(input.as_bytes()[end - 1], b'.' | b'-' | b'_') {
        end -= 1;
    }
    let candidate = &input[start..end];
    let (local, domain) = candidate.split_once('@')?;
    if local.is_empty()
        || domain.is_empty()
        || domain.contains('@')
        || !domain.contains('.')
        || !domain
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'-'))
    {
        return None;
    }
    Some((end, REDACTED_EMAIL))
}

fn detect_ipv4(input: &str, start: usize) -> Option<(usize, &'static str)> {
    if !input.as_bytes()[start].is_ascii_digit()
        || start > 0 && matches!(input.as_bytes()[start - 1], b'0'..=b'9' | b'.')
    {
        return None;
    }
    let mut end = consume_while(input, start, |byte| byte.is_ascii_digit() || byte == b'.');
    while end > start && input.as_bytes()[end - 1] == b'.' {
        end -= 1;
    }
    Ipv4Addr::from_str(&input[start..end])
        .ok()
        .map(|_| (end, REDACTED_IP))
}

fn detect_bracketed_ipv6(input: &str, start: usize) -> Option<(usize, &'static str)> {
    if input.as_bytes()[start] != b'[' {
        return None;
    }
    let close = input[start + 1..].find(']')? + start + 1;
    let candidate = &input[start + 1..close];
    let address = candidate.split('%').next().unwrap_or(candidate);
    Ipv6Addr::from_str(address)
        .ok()
        .map(|_| (close + 1, REDACTED_IP))
}

fn detect_ipv6(input: &str, start: usize) -> Option<(usize, &'static str)> {
    let first = input.as_bytes()[start];
    if !(first.is_ascii_hexdigit() || first == b':') || !is_ipv6_boundary(input, start) {
        return None;
    }
    let end = consume_while(input, start, |byte| {
        byte.is_ascii_hexdigit() || matches!(byte, b':' | b'.' | b'%' | b'_' | b'-')
    });
    let candidate = &input[start..end];
    if candidate.bytes().filter(|byte| *byte == b':').count() < 2 {
        return None;
    }
    let address = candidate.split('%').next().unwrap_or(candidate);
    Ipv6Addr::from_str(address).ok().map(|_| (end, REDACTED_IP))
}

fn starts_with_ascii_case_insensitive(value: &str, prefix: &str) -> bool {
    value
        .get(..prefix.len())
        .map(|candidate| candidate.eq_ignore_ascii_case(prefix))
        .unwrap_or(false)
}

fn is_path_boundary(input: &str, start: usize) -> bool {
    start == 0
        || input[..start]
            .chars()
            .next_back()
            .map(|character| {
                character.is_whitespace()
                    || matches!(character, '(' | '[' | '{' | '"' | '\'' | '=' | ':')
            })
            .unwrap_or(true)
}

fn is_word_boundary(input: &str, start: usize) -> bool {
    start == 0
        || !input.as_bytes()[start - 1].is_ascii_alphanumeric()
            && input.as_bytes()[start - 1] != b'_'
}

fn is_word_end(input: &str, end: usize) -> bool {
    end >= input.len()
        || !input.as_bytes()[end].is_ascii_alphanumeric() && input.as_bytes()[end] != b'_'
}

fn is_token_boundary(input: &str, start: usize) -> bool {
    start == 0
        || !matches!(
            input.as_bytes()[start - 1],
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'_' | b'-'
        )
}

fn is_email_boundary(input: &str, start: usize) -> bool {
    start == 0 || !is_email_candidate_byte(input.as_bytes()[start - 1])
}

fn is_ipv6_boundary(input: &str, start: usize) -> bool {
    start == 0
        || !matches!(
            input.as_bytes()[start - 1],
            b'A'..=b'F' | b'a'..=b'f' | b'0'..=b'9' | b':'
        )
}

fn is_email_local_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'+' | b'-')
}

fn is_email_candidate_byte(byte: u8) -> bool {
    is_email_local_byte(byte) || byte == b'@'
}

fn skip_ascii_whitespace(input: &str, mut cursor: usize) -> usize {
    while cursor < input.len() && input.as_bytes()[cursor].is_ascii_whitespace() {
        cursor += 1;
    }
    cursor
}

fn skip_ascii_whitespace_and_quotes(input: &str, mut cursor: usize) -> usize {
    while cursor < input.len()
        && (input.as_bytes()[cursor].is_ascii_whitespace()
            || matches!(input.as_bytes()[cursor], b'"' | b'\''))
    {
        cursor += 1;
    }
    cursor
}

fn consume_secret_value(input: &str, start: usize) -> usize {
    let mut end = start;
    while end < input.len() {
        let character = input[end..]
            .chars()
            .next()
            .expect("cursor is inside the string");
        if character.is_whitespace()
            || matches!(
                character,
                '"' | '\'' | ',' | ';' | '}' | ']' | ')' | '<' | '>'
            )
        {
            break;
        }
        end += character.len_utf8();
    }
    end
}

fn consume_until(input: &str, start: usize, stop: impl Fn(char) -> bool) -> usize {
    let mut end = start;
    while end < input.len() {
        let character = input[end..]
            .chars()
            .next()
            .expect("cursor is inside the string");
        if stop(character) {
            break;
        }
        end += character.len_utf8();
    }
    end
}

fn consume_while(input: &str, start: usize, keep: impl Fn(u8) -> bool) -> usize {
    let mut end = start;
    while end < input.len() && input.as_bytes()[end].is_ascii() && keep(input.as_bytes()[end]) {
        end += 1;
    }
    end
}

pub fn payload_digest(envelope: &IncidentEnvelope) -> Result<String, DiagnosticsError> {
    let canonical = serde_json::to_vec(envelope).map_err(|_| DiagnosticsError::Serialization)?;
    // This digest is an idempotency equality marker, not an authentication or
    // credential primitive. FNV-1a 128 is stable across processes and releases.
    let mut hash = 0x6c62272e07bb014262b821756295c58du128;
    const PRIME: u128 = 0x0000000001000000000000000000013b;
    for byte in canonical {
        hash ^= u128::from(byte);
        hash = hash.wrapping_mul(PRIME);
    }
    Ok(format!("fnv1a128:{hash:032x}"))
}

fn identity_digest(key: &[u8; IDENTITY_KEY_BYTES], identity: &str) -> String {
    let mut mac = Hmac::<Sha256>::new_from_slice(key).expect("HMAC accepts any key length");
    mac.update(b"echo-diagnostics-identity-v1\0");
    mac.update(identity.as_bytes());
    let bytes = mac.finalize().into_bytes();
    let mut digest = String::with_capacity("hmac-sha256:".len() + bytes.len() * 2);
    digest.push_str("hmac-sha256:");
    for byte in bytes {
        use fmt::Write as _;
        write!(&mut digest, "{byte:02x}").expect("writing to a String cannot fail");
    }
    digest
}

fn validate_identity_digest(value: &str) -> bool {
    value.strip_prefix("hmac-sha256:").is_some_and(|hex| {
        hex.len() == 64
            && hex
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
    })
}

fn generate_unique_incident_id(index: &StoreIndex) -> Result<String, DiagnosticsError> {
    for _ in 0..8 {
        let mut random = [0u8; 16];
        OsRng.fill_bytes(&mut random);
        let mut id = String::with_capacity(INCIDENT_ID_PREFIX.len() + 32);
        id.push_str(INCIDENT_ID_PREFIX);
        for byte in random {
            use fmt::Write as _;
            write!(&mut id, "{byte:02x}").map_err(|_| DiagnosticsError::Serialization)?;
        }
        if !index.by_incident_id.contains_key(&id) {
            return Ok(id);
        }
    }
    Err(DiagnosticsError::Serialization)
}

fn append_json_line(path: &Path, line: &[u8]) -> io::Result<()> {
    let mut file = OpenOptions::new()
        .create(true)
        .read(true)
        .append(true)
        .open(path)?;
    let length = file.metadata()?.len();
    if length > 0 {
        file.seek(SeekFrom::End(-1))?;
        let mut last = [0u8; 1];
        file.read_exact(&mut last)?;
        if last[0] != b'\n' {
            file.write_all(b"\n")?;
        }
    }
    file.write_all(line)?;
    file.write_all(b"\n")?;
    file.sync_data()
}

fn storage_file_name(timestamp_ms: u64) -> String {
    let day = (timestamp_ms / MILLIS_PER_DAY) as i64;
    let (year, month, day_of_month) = civil_from_days(day);
    format!("{STORAGE_PREFIX}{year:04}-{month:02}-{day_of_month:02}{STORAGE_SUFFIX}")
}

fn parse_storage_file_name(file_name: &str) -> Option<i64> {
    let date = file_name
        .strip_prefix(STORAGE_PREFIX)?
        .strip_suffix(STORAGE_SUFFIX)?;
    if date.len() != 10 || date.as_bytes()[4] != b'-' || date.as_bytes()[7] != b'-' {
        return None;
    }
    let year = date[..4].parse::<i32>().ok()?;
    let month = date[5..7].parse::<u32>().ok()?;
    let day = date[8..10].parse::<u32>().ok()?;
    if !(1..=12).contains(&month) || !(1..=31).contains(&day) {
        return None;
    }
    let days = days_from_civil(year, month, day);
    let (round_year, round_month, round_day) = civil_from_days(days);
    (round_year == year && round_month == month && round_day == day).then_some(days)
}

fn checked_storage_path(root: &Path, file_name: &str) -> Result<PathBuf, DiagnosticsError> {
    if parse_storage_file_name(file_name).is_none()
        || Path::new(file_name)
            .file_name()
            .and_then(|name| name.to_str())
            != Some(file_name)
    {
        return Err(ValidationError::InvalidIdentifier("storage_file").into());
    }
    Ok(root.join(file_name))
}

// Howard Hinnant's civil calendar conversion, with day zero at 1970-01-01.
fn civil_from_days(days_since_epoch: i64) -> (i32, u32, u32) {
    let z = days_since_epoch + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let day_of_era = z - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let mut year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_prime = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    year += i64::from(month <= 2);
    (year as i32, month as u32, day as u32)
}

fn days_from_civil(year: i32, month: u32, day: u32) -> i64 {
    let adjusted_year = i64::from(year) - i64::from(month <= 2);
    let era = if adjusted_year >= 0 {
        adjusted_year
    } else {
        adjusted_year - 399
    } / 400;
    let year_of_era = adjusted_year - era * 400;
    let month_prime = i64::from(month) + if month > 2 { -3 } else { 9 };
    let day_of_year = (153 * month_prime + 2) / 5 + i64::from(day) - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

fn storage_files(root: &Path) -> io::Result<Vec<(i64, String, PathBuf, u64)>> {
    let mut files = Vec::new();
    for entry in fs::read_dir(root)? {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
            continue;
        };
        let Some(day) = parse_storage_file_name(&file_name) else {
            continue;
        };
        let bytes = entry.metadata()?.len();
        files.push((day, file_name, entry.path(), bytes));
    }
    files.sort_by(|left, right| left.0.cmp(&right.0).then_with(|| left.1.cmp(&right.1)));
    Ok(files)
}

fn load_index(root: &Path) -> Result<StoreIndex, DiagnosticsError> {
    let mut index = StoreIndex::default();
    for_each_record(root, |record, file_name| {
        if record.record_version != STORED_RECORD_VERSION
            || validate_incident_id(&record.incident_id).is_err()
            || validate_uuid(&record.envelope.envelope_id, "envelope_id").is_err()
            || !validate_identity_digest(&record.authenticated_identity_digest)
        {
            return;
        }
        let entry = IndexEntry {
            incident_id: record.incident_id.clone(),
            payload_digest: record.payload_digest.clone(),
            file_name: file_name.to_owned(),
        };
        index
            .by_envelope_key
            .entry((
                record.authenticated_identity_digest.clone(),
                record.envelope.envelope_id.clone(),
            ))
            .or_insert_with(|| entry.clone());
        index
            .by_incident_id
            .entry(record.incident_id)
            .or_insert(entry);
    })?;
    Ok(index)
}

fn for_each_record(
    root: &Path,
    mut visit: impl FnMut(StoredIncident, &str),
) -> Result<(), DiagnosticsError> {
    for (_, file_name, path, _) in storage_files(root)? {
        read_jsonl_records(&path, |record| {
            visit(record, &file_name);
            false
        })?;
    }
    Ok(())
}

fn find_record(path: &Path, incident_id: &str) -> Result<Option<StoredIncident>, DiagnosticsError> {
    let mut found = None;
    read_jsonl_records(path, |record| {
        if record.incident_id == incident_id {
            found = Some(record);
            true
        } else {
            false
        }
    })?;
    Ok(found)
}

/// Streams bounded JSONL records without turning malformed JSON or torn UTF-8
/// tails into false disk-I/O failures. Oversized lines are drained without
/// growing the buffer beyond the shared stored-record ceiling.
fn read_jsonl_records(
    path: &Path,
    mut visit: impl FnMut(StoredIncident) -> bool,
) -> io::Result<()> {
    let mut reader = BufReader::new(File::open(path)?);
    let mut line = Vec::new();
    loop {
        line.clear();
        let mut oversized = false;
        let mut reached_eof = false;
        loop {
            let buffer = reader.fill_buf()?;
            if buffer.is_empty() {
                reached_eof = true;
                break;
            }
            let newline = buffer.iter().position(|byte| *byte == b'\n');
            let consumed = newline.map(|index| index + 1).unwrap_or(buffer.len());
            if !oversized {
                if line.len().saturating_add(consumed) <= MAX_STORED_RECORD_BYTES + 1 {
                    line.extend_from_slice(&buffer[..consumed]);
                } else {
                    oversized = true;
                    line.clear();
                }
            }
            reader.consume(consumed);
            if newline.is_some() {
                break;
            }
        }

        if !oversized && !line.is_empty() {
            while matches!(line.last(), Some(b'\n' | b'\r')) {
                line.pop();
            }
            if line.len() <= MAX_STORED_RECORD_BYTES {
                if let Ok(mut record) = serde_json::from_slice::<StoredIncident>(&line) {
                    sanitize_stored_incident(&mut record);
                    if visit(record) {
                        return Ok(());
                    }
                }
            }
        }
        if reached_eof {
            return Ok(());
        }
    }
}

fn sort_summaries(summaries: &mut [IncidentSummary]) {
    summaries.sort_by(|left, right| {
        right
            .received_at_ms
            .cmp(&left.received_at_ms)
            .then_with(|| right.incident_id.cmp(&left.incident_id))
    });
}

fn rewrite_without_incident(path: &Path, incident_id: &str) -> io::Result<bool> {
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "invalid diagnostics file"))?;
    if parse_storage_file_name(file_name).is_none() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "invalid diagnostics file",
        ));
    }

    let mut random = [0u8; 8];
    OsRng.fill_bytes(&mut random);
    let suffix = random
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let temp_path = path.with_file_name(format!("{file_name}.{suffix}.tmp"));
    let backup_path = path.with_file_name(format!("{file_name}.bak"));
    let mut output = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temp_path)?;
    let mut removed = false;
    let reader = BufReader::new(File::open(path)?);
    for line in reader.lines() {
        let line = line?;
        let matches = serde_json::from_str::<StoredIncident>(&line)
            .map(|record| record.incident_id == incident_id)
            .unwrap_or(false);
        if matches {
            removed = true;
            continue;
        }
        output.write_all(line.as_bytes())?;
        output.write_all(b"\n")?;
    }
    output.sync_all()?;
    drop(output);

    if !removed {
        let _ = fs::remove_file(&temp_path);
        return Ok(false);
    }
    commit_rewrite(path, &temp_path, &backup_path)?;
    Ok(true)
}

fn commit_rewrite(path: &Path, temp_path: &Path, backup_path: &Path) -> io::Result<()> {
    if backup_path.exists() {
        fs::remove_file(backup_path)?;
    }
    fs::rename(path, backup_path)?;
    if let Err(swap_error) = fs::rename(temp_path, path) {
        let rollback = fs::rename(backup_path, path);
        let _ = fs::remove_file(temp_path);
        if rollback.is_err() {
            return Err(io::Error::other(
                "diagnostics rewrite swap and rollback failed",
            ));
        }
        return Err(swap_error);
    }

    // The replacement is committed once temp -> original succeeds. Backup
    // cleanup is recoverable housekeeping and must not turn a committed delete
    // or prune into a false failure.
    let _ = fs::remove_file(backup_path);
    Ok(())
}

fn recover_rewrite_artifacts(root: &Path) -> io::Result<()> {
    let mut artifacts = Vec::new();
    for entry in fs::read_dir(root)? {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let Some(file_name) = entry.file_name().to_str().map(str::to_owned) else {
            continue;
        };
        artifacts.push((file_name, entry.path()));
    }
    artifacts.sort_by(|left, right| left.0.cmp(&right.0));

    // Restore authoritative backups first. Cleanup of obsolete artifacts is a
    // separate best-effort pass so a locked temp file cannot prevent recovery
    // of a missing original.
    for (file_name, path) in &artifacts {
        if let Some(original_name) = file_name.strip_suffix(".bak") {
            if parse_storage_file_name(original_name).is_some() {
                let original = root.join(original_name);
                if !original.exists() {
                    fs::rename(path, original)?;
                }
            }
        }
    }

    for (file_name, path) in &artifacts {
        if let Some(original_name) = file_name.strip_suffix(".bak") {
            if parse_storage_file_name(original_name).is_some() && root.join(original_name).exists()
            {
                let _ = fs::remove_file(path);
            }
            continue;
        }
        if let Some(without_tmp) = file_name.strip_suffix(".tmp") {
            let Some((original_name, random_suffix)) = without_tmp.rsplit_once('.') else {
                continue;
            };
            if parse_storage_file_name(original_name).is_some()
                && random_suffix.len() == 16
                && random_suffix.bytes().all(|byte| byte.is_ascii_hexdigit())
            {
                let _ = fs::remove_file(path);
            }
        }
    }
    Ok(())
}

fn recover_store_state(root: &Path) -> io::Result<()> {
    recover_rewrite_artifacts(root)?;
    recover_crash_tails(root)
}

fn recover_crash_tails(root: &Path) -> io::Result<()> {
    const SEARCH_CHUNK_BYTES: u64 = 8 * 1024;
    for (_, _, path, bytes) in storage_files(root)? {
        if bytes == 0 {
            continue;
        }
        let mut file = OpenOptions::new().read(true).write(true).open(path)?;
        file.seek(SeekFrom::End(-1))?;
        let mut last = [0_u8; 1];
        file.read_exact(&mut last)?;
        if last[0] == b'\n' {
            continue;
        }

        let mut search_end = bytes;
        let mut truncate_at = 0_u64;
        while search_end > 0 {
            let search_start = search_end.saturating_sub(SEARCH_CHUNK_BYTES);
            let length = (search_end - search_start) as usize;
            let mut chunk = vec![0_u8; length];
            file.seek(SeekFrom::Start(search_start))?;
            file.read_exact(&mut chunk)?;
            if let Some(newline) = chunk.iter().rposition(|byte| *byte == b'\n') {
                truncate_at = search_start + newline as u64 + 1;
                break;
            }
            search_end = search_start;
        }
        file.set_len(truncate_at)?;
        file.sync_data()?;
    }
    Ok(())
}

#[derive(Debug, Default)]
struct AppendPruneReport {
    changed: bool,
}

/// Makes room before an append while the store's process-local I/O lock is
/// held. Whole old days are removed first. If the cap is reached within the
/// current day, the oldest complete JSONL records are removed through an
/// atomic rewrite. The incoming record is not on disk yet, so it can never be
/// selected for eviction and then incorrectly acknowledged.
fn prune_for_append(
    root: &Path,
    now_ms: u64,
    policy: &RetentionPolicy,
    incoming_bytes: u64,
) -> Result<AppendPruneReport, DiagnosticsError> {
    if incoming_bytes > policy.max_total_bytes {
        return Err(DiagnosticsError::CapacityExceeded);
    }

    recover_rewrite_artifacts(root)?;
    let files = storage_files(root)?;
    let cutoff_ms = now_ms.saturating_sub(duration_millis_saturating(policy.max_age));
    let cutoff_day = (cutoff_ms / MILLIS_PER_DAY) as i64;
    let mut removed = vec![false; files.len()];
    let mut retained_bytes = files.iter().map(|file| file.3).sum::<u64>();
    let mut report = AppendPruneReport::default();

    for (index, (day, _, path, bytes)) in files.iter().enumerate() {
        if *day < cutoff_day {
            fs::remove_file(path)?;
            removed[index] = true;
            retained_bytes = retained_bytes.saturating_sub(*bytes);
            report.changed = true;
        }
    }

    let maximum_existing_bytes = policy.max_total_bytes - incoming_bytes;
    if retained_bytes > maximum_existing_bytes {
        // Evict a bounded batch rather than rewriting the oldest JSONL file for
        // every subsequent record while the store hovers exactly at its cap.
        let headroom = (policy.max_total_bytes / 10).min(MAX_CAP_EVICTION_HEADROOM_BYTES);
        let eviction_target = maximum_existing_bytes.saturating_sub(headroom);
        for (index, (_, _, path, bytes)) in files.iter().enumerate() {
            if retained_bytes <= eviction_target {
                break;
            }
            if removed[index] {
                continue;
            }

            let bytes_needed = retained_bytes - eviction_target;
            if *bytes <= bytes_needed {
                fs::remove_file(path)?;
                retained_bytes = retained_bytes.saturating_sub(*bytes);
                report.changed = true;
                continue;
            }

            let freed = rewrite_drop_oldest_bytes(path, bytes_needed)?;
            if freed == 0 {
                return Err(DiagnosticsError::CapacityExceeded);
            }
            retained_bytes = retained_bytes.saturating_sub(freed);
            report.changed = true;
        }
    }

    if retained_bytes > maximum_existing_bytes {
        return Err(DiagnosticsError::CapacityExceeded);
    }
    Ok(report)
}

fn rewrite_drop_oldest_bytes(path: &Path, minimum_bytes: u64) -> io::Result<u64> {
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "invalid diagnostics file"))?;
    if parse_storage_file_name(file_name).is_none() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "invalid diagnostics file",
        ));
    }

    let original_bytes = fs::metadata(path)?.len();
    let mut random = [0u8; 8];
    OsRng.fill_bytes(&mut random);
    let suffix = random
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let temp_path = path.with_file_name(format!("{file_name}.{suffix}.tmp"));
    let backup_path = path.with_file_name(format!("{file_name}.bak"));
    let mut output = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temp_path)?;
    let mut reader = BufReader::new(File::open(path)?);
    let mut discarded = 0_u64;
    let mut line = Vec::new();
    while discarded < minimum_bytes {
        line.clear();
        let read = reader.read_until(b'\n', &mut line)?;
        if read == 0 {
            break;
        }
        discarded = discarded.saturating_add(read as u64);
    }
    io::copy(&mut reader, &mut output)?;
    output.sync_all()?;
    drop(output);

    commit_rewrite(path, &temp_path, &backup_path)?;

    let retained_bytes = fs::metadata(path)?.len();
    Ok(original_bytes.saturating_sub(retained_bytes))
}

pub fn prune_directory(
    root: &Path,
    now_ms: u64,
    policy: &RetentionPolicy,
) -> Result<PruneReport, DiagnosticsError> {
    recover_rewrite_artifacts(root)?;
    let files = storage_files(root)?;
    let cutoff_ms = now_ms.saturating_sub(duration_millis_saturating(policy.max_age));
    let cutoff_day = (cutoff_ms / MILLIS_PER_DAY) as i64;
    let mut removed = vec![false; files.len()];
    let mut report = PruneReport::default();
    let mut retained_bytes = files.iter().map(|file| file.3).sum::<u64>();

    for (index, (day, file_name, path, bytes)) in files.iter().enumerate() {
        if *day < cutoff_day {
            fs::remove_file(path)?;
            removed[index] = true;
            retained_bytes = retained_bytes.saturating_sub(*bytes);
            report.removed_bytes = report.removed_bytes.saturating_add(*bytes);
            report.removed_files.push(file_name.clone());
        }
    }

    if retained_bytes > policy.max_total_bytes {
        for (index, (_, file_name, path, bytes)) in files.iter().enumerate() {
            if retained_bytes <= policy.max_total_bytes {
                break;
            }
            if removed[index] {
                continue;
            }
            fs::remove_file(path)?;
            retained_bytes = retained_bytes.saturating_sub(*bytes);
            report.removed_bytes = report.removed_bytes.saturating_add(*bytes);
            report.removed_files.push(file_name.clone());
        }
    }
    report.retained_bytes = retained_bytes;
    Ok(report)
}

fn duration_millis_saturating(duration: Duration) -> u64 {
    duration.as_millis().min(u128::from(u64::MAX)) as u64
}

