    #[test]
    fn reopen_truncates_a_torn_invalid_utf8_tail() {
        let directory = TestDirectory::new();
        let store = DiagnosticStore::open(&directory.0).expect("open store");
        let incident_id = match store
            .append("Example Tester", envelope(1), NOW)
            .expect("store incident")
        {
            AppendOutcome::Stored { incident_id } => incident_id,
            other => panic!("unexpected outcome: {other:?}"),
        };
        let path = storage_files(&directory.0).expect("list files")[0]
            .2
            .clone();
        let clean_length = fs::metadata(&path).expect("clean metadata").len();
        drop(store);

        let mut file = OpenOptions::new()
            .append(true)
            .open(&path)
            .expect("open torn tail");
        file.write_all(&[0xff, 0xfe, 0xfd])
            .expect("write invalid UTF-8 tail");
        file.sync_data().expect("sync torn tail");
        drop(file);

        let reopened = DiagnosticStore::open(&directory.0).expect("recover store");
        assert_eq!(
            fs::metadata(&path).expect("recovered metadata").len(),
            clean_length
        );
        assert!(reopened
            .get_incident(&incident_id)
            .expect("read recovered incident")
            .is_some());
    }

    #[test]
    fn reconciliation_indexes_a_complete_ambiguous_append_once() {
        let directory = TestDirectory::new();
        let store = DiagnosticStore::open(&directory.0).expect("open store");
        store
            .append("Example Tester", envelope(1), NOW)
            .expect("store first incident");

        let mut second = envelope(2);
        sanitize_envelope(&mut second);
        let digest = payload_digest(&second).expect("digest second envelope");
        let incident_id = "inc_11111111111111111111111111111111".to_string();
        let record = StoredIncident {
            record_version: STORED_RECORD_VERSION,
            incident_id: incident_id.clone(),
            received_at_ms: NOW,
            authenticated_identity: "Example Tester".to_string(),
            authenticated_identity_digest: identity_digest(&store.identity_key, "Example Tester"),
            payload_digest: digest,
            envelope: second.clone(),
        };
        let line = serde_json::to_vec(&record).expect("serialize ambiguous record");
        let path = directory.0.join(storage_file_name(NOW));
        append_json_line(&path, &line).expect("write complete ambiguous record");

        {
            let mut index = store.index.lock().expect("lock stale index");
            store.reconcile_or_poison(&mut index);
        }
        assert!(!store.poisoned.load(Ordering::Acquire));
        assert!(matches!(
            store.append("Example Tester", second, NOW),
            Ok(AppendOutcome::Duplicate { incident_id: duplicate }) if duplicate == incident_id
        ));
        assert_eq!(
            fs::read_to_string(path)
                .expect("read records")
                .lines()
                .count(),
            2
        );
    }

    #[test]
    fn diagnostics_storage_cannot_overlap_a_static_root() {
        let directory = TestDirectory::new();
        let viewer = directory.0.join("viewer");
        let sibling = directory.0.join("private-diagnostics");
        fs::create_dir_all(&viewer).expect("create viewer root");

        assert!(
            storage_path_overlaps(&viewer.join("diagnostics"), &[&viewer])
                .expect("check nested path")
        );
        assert!(storage_path_overlaps(&directory.0, &[&viewer]).expect("check ancestor path"));
        assert!(!storage_path_overlaps(&sibling, &[&viewer]).expect("check sibling path"));
        assert!(storage_path_overlaps(
            &directory.0.join("missing").join("..").join("viewer"),
            &[&viewer]
        )
        .expect("normalize parent components"));
    }

    #[test]
    fn diagnostics_storage_rejects_links_below_a_static_root() {
        let directory = TestDirectory::new();
        let viewer = directory.0.join("viewer");
        let diagnostics = directory.0.join("private-diagnostics");
        fs::create_dir_all(&viewer).expect("create viewer root");
        fs::create_dir_all(&diagnostics).expect("create diagnostics root");
        let link = viewer.join("linked-diagnostics");

        #[cfg(windows)]
        let link_result = std::os::windows::fs::symlink_dir(&diagnostics, &link);
        #[cfg(unix)]
        let link_result = std::os::unix::fs::symlink(&diagnostics, &link);
        match link_result {
            Ok(()) => {}
            Err(error)
                if matches!(
                    error.kind(),
                    io::ErrorKind::PermissionDenied | io::ErrorKind::Unsupported
                ) || error.raw_os_error() == Some(1314) =>
            {
                return;
            }
            Err(error) => panic!("create static-root link: {error}"),
        }

        assert!(storage_path_overlaps(&diagnostics, &[&viewer])
            .expect("reject descendant filesystem link"));
    }
